// Min-heap state: (distance, vertex_id)
using Edge = std::pair<int, int>;

std::vector<int> dijkstra(int n, int src, const std::vector<std::vector<Edge>>& adj) {
    const int INF = std::numeric_limits<int>::max();
    std::vector<int> dist(n, INF);
    dist[src] = 0;

    // Min-heap ordering: lowest distance on top
    std::priority_queue<Edge, std::vector<Edge>, std::greater<Edge>> pq;
    pq.push({0, src});

    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();

        // Lazy deletion check: skip stale entries
        if (d > dist[u]) continue;

        // Edge relaxation loop
        for (const auto& [v, weight] : adj[u]) {
            if (dist[u] + weight < dist[v]) {
                dist[v] = dist[u] + weight;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

import { useState, useEffect, useRef } from 'react';

export function useDebounce<T>(val: T, delay: number): T {
  const [debounced, setDebounced] = useState<T>(val);

  useEffect(() => {
    const handler = setTimeout(() => setDebounced(val), delay);
    return () => clearTimeout(handler);
  }, [val, delay]);

  return debounced;
}

export function useThrottle<T extends (...args: any[]) => any>(fn: T, limit: number): T {
  const inThrottle = useRef(false);
  return ((...args: any[]) => {
    if (!inThrottle.current) {
      fn(...args);
      inThrottle.current = true;
      setTimeout(() => { inThrottle.current = false; }, limit);
    }
  }) as T;
}

