const int MOD = 1e9 + 7;

long long power(long long base, long long exp, long long mod = MOD) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

long long modInverse(long long n, long long p = MOD) {
    return power(n, p - 2, p); // Fermat's Little Theorem (p is prime)
}

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

pub struct RingBuffer<T> {
    buffer: Vec<Option<T>>,
    capacity: usize,
    head: AtomicUsize,
    tail: AtomicUsize,
}

impl<T: Clone> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        Self {
            buffer: vec![None; capacity],
            capacity,
            head: AtomicUsize::new(0),
            tail: AtomicUsize::new(0),
        }
    }

    pub fn try_push(&mut self, item: T) -> Result<(), &'static str> {
        let head = self.head.load(Ordering::Acquire);
        let tail = self.tail.load(Ordering::Relaxed);

        if (tail + 1) % self.capacity == head {
            return Err("Buffer full");
        }

        self.buffer[tail] = Some(item);
        self.tail.store((tail + 1) % self.capacity, Ordering::Release);
        Ok(())
    }
}

public class LLRBTree<Key extends Comparable<Key>, Value> {
    private static final boolean RED = true;
    private static final boolean BLACK = false;

    private class Node {
        Key key; Value val; Node left, right;
        boolean color; // color of parent link
        Node(Key key, Value val, boolean color) {
            this.key = key; this.val = val; this.color = color;
        }
    }

    private boolean isRed(Node x) { return x != null && x.color == RED; }

    private Node rotateLeft(Node h) {
        Node x = h.right;
        h.right = x.left;
        x.left = h;
        x.color = h.color;
        h.color = RED;
        return x;
    }

    private Node rotateRight(Node h) {
        Node x = h.left;
        h.left = x.right;
        x.right = h;
        x.color = h.color;
        h.color = RED;
        return x;
    }

    private void flipColors(Node h) {
        h.color = !h.color;
        h.left.color = !h.left.color;
        h.right.color = !h.right.color;
    }
}

def merge_sort(arr: list[int]) -> list[int]:
    """Divide-and-conquer merge sort returning a newly sorted array."""
    if len(arr) <= 1:
        return arr

    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left: list[int], right: list[int]) -> list[int]:
    merged = []
    i = j = 0

    # Two-pointer linear scan
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1

    # Append remaining elements
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged

class TrieNode {
  children: Map<string, TrieNode> = new Map();
  isEndOfWord: boolean = false;
}

export class Trie {
  private root: TrieNode = new TrieNode();

  insert(word: string): void {
    let current = this.root;
    for (const char of word) {
      if (!current.children.has(char)) {
        current.children.set(char, new TrieNode());
      }
      current = current.children.get(char)!;
    }
    current.isEndOfWord = true;
  }

  search(word: string): boolean {
    const node = this.traverse(word);
    return node !== null && node.isEndOfWord;
  }

  startsWith(prefix: string): boolean {
    return this.traverse(prefix) !== null;
  }

  private traverse(prefix: string): TrieNode | null {
    let current = this.root;
    for (const char of prefix) {
      if (!current.children.has(char)) return null;
      current = current.children.get(char)!;
    }
    return current;
  }
}

public class KadaneSubarray {
    public static class SubarrayResult {
        public int maxSum;
        public int startIndex;
        public int endIndex;

        public SubarrayResult(int maxSum, int startIndex, int endIndex) {
            this.maxSum = maxSum;
            this.startIndex = startIndex;
            this.endIndex = endIndex;
        }
    }

    public static SubarrayResult findMaxSubarray(int[] nums) {
        if (nums == null || nums.length == 0) {
            throw new IllegalArgumentException("Input array cannot be empty");
        }

        int maxSoFar = nums[0];
        int currentMax = nums[0];
        int start = 0, end = 0, tempStart = 0;

        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > currentMax + nums[i]) {
                currentMax = nums[i];
                tempStart = i;
            } else {
                currentMax += nums[i];
            }

            if (currentMax > maxSoFar) {
                maxSoFar = currentMax;
                start = tempStart;
                end = i;
            }
        }
        return new SubarrayResult(maxSoFar, start, end);
    }
}

#include <vector>
#include <queue>
#include <iostream>

std::vector<int> topologicalSortKahn(int n, const std::vector<std::pair<int, int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    std::vector<int> inDegree(n, 0);

    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        inDegree[v]++;
    }

    std::queue<int> q;
    for (int i = 0; i < n; i++) {
        if (inDegree[i] == 0) q.push(i);
    }

    std::vector<int> topoOrder;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        topoOrder.push_back(u);

        for (int v : adj[u]) {
            if (--inDegree[v] == 0) {
                q.push(v);
            }
        }
    }

    // Cycle detection check: if topoOrder size != n, cycle exists
    if (topoOrder.size() != static_cast<size_t>(n)) {
        return {}; // Directed cycle detected
    }
    return topoOrder;
}

use std::sync::{Arc, RwLock};
use std::thread;
use std::time::Duration;

#[derive(Debug)]
struct SharedState {
    counter: u64,
    status: String,
}

fn main() {
    let state = Arc::new(RwLock::new(SharedState {
        counter: 0,
        status: "INITIALIZED".to_string(),
    }));

    let mut handles = vec![];

    // Spawn 4 concurrent reader threads
    for id in 0..4 {
        let state_clone = Arc::clone(&state);
        handles.push(thread::spawn(move || {
            let lock = state_clone.read().unwrap();
            println!("Reader {}: counter={}, status={}", id, lock.counter, lock.status);
        }));
    }

    // Spawn 1 exclusive writer thread
    let writer_state = Arc::clone(&state);
    handles.push(thread::spawn(move || {
        let mut lock = writer_state.write().unwrap();
        lock.counter += 42;
        lock.status = "MUTATED_EXCLUSIVE".to_string();
        println!("Writer finalized state mutation");
    }));

    for h in handles {
        h.join().unwrap();
    }
}
